import{_ as e,o as t,c as s,a3 as i}from"./chunks/framework.BlfGB29P.js";const k=JSON.parse('{"title":"规范、设计文档与版本证据","description":"","frontmatter":{"title":"规范、设计文档与版本证据","outline":[2,3],"article":{"type":"concept","structure":"concept"}},"headers":[],"relativePath":"frontend/deep-dive/research/specs-design-evidence.md","filePath":"frontend/deep-dive/research/specs-design-evidence.md","lastUpdated":1785589115000}'),r={name:"frontend/deep-dive/research/specs-design-evidence.md"};function n(l,a,h,o,d,p){return t(),s("div",null,[...a[0]||(a[0]=[i(`<h1 id="规范、设计文档与版本证据" tabindex="-1">规范、设计文档与版本证据 <a class="header-anchor" href="#规范、设计文档与版本证据" aria-label="Permalink to &quot;规范、设计文档与版本证据&quot;">​</a></h1><blockquote><p>作者：codex-gpt-sol-5.6</p></blockquote><p>原理结论的可信度取决于证据能否匹配它声称的范围。规范能证明跨实现语义，官方设计文档解释取舍，固定版本源码说明当前实现，实验只证明给定环境的观测。把四者混为“资料链接”会产生过度结论。本文给出可执行的证据层级与一份填写完成的结论卡。</p><h2 id="_1-证据层级" tabindex="-1">1. 证据层级 <a class="header-anchor" href="#_1-证据层级" aria-label="Permalink to &quot;1. 证据层级&quot;">​</a></h2><h3 id="_1-1-正式规范" tabindex="-1">1.1 正式规范 <a class="header-anchor" href="#_1-1-正式规范" aria-label="Permalink to &quot;1.1 正式规范&quot;">​</a></h3><p>ECMAScript、WHATWG HTML、W3C 等规范适合支持术语、算法步骤和跨实现可观察行为。规范版本和 status 很重要：草案、已发布版本与实现支持不同。规范通常不承诺性能、内部队列名称或 GC 时机。</p><h3 id="_1-2-官方设计与文档" tabindex="-1">1.2 官方设计与文档 <a class="header-anchor" href="#_1-2-官方设计与文档" aria-label="Permalink to &quot;1.2 官方设计与文档&quot;">​</a></h3><p>设计文档、RFC、release note 和 API 文档说明维护者意图、兼容性与公开契约。它们可能滞后于实现，也可能描述计划而非已发布行为；引用时记录版本、发布日期或对应 release。</p><h3 id="_1-3-固定源码与测试" tabindex="-1">1.3 固定源码与测试 <a class="header-anchor" href="#_1-3-固定源码与测试" aria-label="Permalink to &quot;1.3 固定源码与测试&quot;">​</a></h3><p>源码回答“某 tag/commit 如何实现”，测试常揭示维护者锁定的行为。证据必须使用永久链接或 commit hash，记录文件、符号和上下文；未经固定的 main 分支只能作为线索，不能支撑历史结论。</p><h3 id="_1-4-可复现实验" tabindex="-1">1.4 可复现实验 <a class="header-anchor" href="#_1-4-可复现实验" aria-label="Permalink to &quot;1.4 可复现实验&quot;">​</a></h3><p>实验提供特定 OS、CPU、运行时版本和输入下的观测。它最擅长证伪或量化，不足以证明所有实现都遵循某个机制。实验脚本、命令、原始输出和环境信息应一起保存。</p><h2 id="_2-从主张选择证据" tabindex="-1">2. 从主张选择证据 <a class="header-anchor" href="#_2-从主张选择证据" aria-label="Permalink to &quot;2. 从主张选择证据&quot;">​</a></h2><h3 id="_2-1-先写可反驳主张" tabindex="-1">2.1 先写可反驳主张 <a class="header-anchor" href="#_2-1-先写可反驳主张" aria-label="Permalink to &quot;2.1 先写可反驳主张&quot;">​</a></h3><p>好主张包含范围，例如“ECMAScript 要求已完成 promise 的 reaction 异步排队”或“Node 20.11 在以下脚本中先运行 promise reaction”。“Promise 一定比 timer 快”没有说明语义、环境或度量，无法验证。</p><h3 id="_2-2-用最窄证据支持最窄结论" tabindex="-1">2.2 用最窄证据支持最窄结论 <a class="header-anchor" href="#_2-2-用最窄证据支持最窄结论" aria-label="Permalink to &quot;2.2 用最窄证据支持最窄结论&quot;">​</a></h3><p>若规范已定义顺序，就引用规范解释必须性；若想解释 V8 的实现，附加固定源码；若量化延迟，再提供 benchmark。单次 Chrome 控制台输出只能支持该实验，不应被提升为语言规范。</p><h3 id="_2-3-处理冲突证据" tabindex="-1">2.3 处理冲突证据 <a class="header-anchor" href="#_2-3-处理冲突证据" aria-label="Permalink to &quot;2.3 处理冲突证据&quot;">​</a></h3><p>规范、文档、源码和实验冲突时，先检查版本、前提、宿主和测量方法。规范定义语义时优先解释可观察结果；实现偏离可能是 bug、实验误读或尚未落地的草案，应明确未知项而非挑选有利证据。</p><h2 id="_3-填写完成的结论卡" tabindex="-1">3. 填写完成的结论卡 <a class="header-anchor" href="#_3-填写完成的结论卡" aria-label="Permalink to &quot;3. 填写完成的结论卡&quot;">​</a></h2><h3 id="_3-1-主张与边界" tabindex="-1">3.1 主张与边界 <a class="header-anchor" href="#_3-1-主张与边界" aria-label="Permalink to &quot;3.1 主张与边界&quot;">​</a></h3><table tabindex="0"><thead><tr><th>项目</th><th>已填写内容</th></tr></thead><tbody><tr><td>主张</td><td>对已 fulfilled 的原生 Promise 注册 <code>then</code> 不会同步调用 handler</td></tr><tr><td>范围</td><td>ECMAScript Promise；不包含用户自定义 thenable 的任意实现</td></tr><tr><td>反例条件</td><td>自建 promise 库可故意同步调用，故不适用</td></tr><tr><td>版本</td><td>ECMAScript 2024；Node 20.x 实验</td></tr><tr><td>影响</td><td>依赖回调同步更新状态的代码存在可重入错误</td></tr></tbody></table><h3 id="_3-2-证据映射" tabindex="-1">3.2 证据映射 <a class="header-anchor" href="#_3-2-证据映射" aria-label="Permalink to &quot;3.2 证据映射&quot;">​</a></h3><table tabindex="0"><thead><tr><th>层级</th><th>证据</th><th>推论</th></tr></thead><tbody><tr><td>规范</td><td><code>PerformPromiseThen</code> 创建 PromiseReactionJob</td><td>reaction 通过 job 排队</td></tr><tr><td>官方文档</td><td>Node <code>queueMicrotask</code> 文档</td><td>宿主微任务观察入口</td></tr><tr><td>实验</td><td><code>trace-order.mjs</code></td><td>当前 Node 输出同步语句在前</td></tr><tr><td>源码</td><td>Node/V8 指定 tag 的实现</td><td>仅用于解释该 tag 的连接方式</td></tr></tbody></table><p>结论写成：“异步 reaction 是 ECMAScript 语义；本实验在 Node 20.x 观察到它早于 timer。V8/Node 内部调度细节为版本敏感实现，不作为 API 依赖。”这比“V8 的 microtask 永远先执行”准确。</p><h2 id="_4-版本固定与链接" tabindex="-1">4. 版本固定与链接 <a class="header-anchor" href="#_4-版本固定与链接" aria-label="Permalink to &quot;4. 版本固定与链接&quot;">​</a></h2><h3 id="_4-1-可重现引用" tabindex="-1">4.1 可重现引用 <a class="header-anchor" href="#_4-1-可重现引用" aria-label="Permalink to &quot;4.1 可重现引用&quot;">​</a></h3><p>源码链接应含 tag 或 commit，例如 <code>https://github.com/microsoft/TypeScript/blob/&lt;commit&gt;/src/compiler/checker.ts</code>。规范引用应含章节锚点和版本/快照日期；实验记录 <code>node --version</code>、<code>process.versions.v8</code>、OS 与命令。</p><h3 id="_4-2-版本敏感标记" tabindex="-1">4.2 版本敏感标记 <a class="header-anchor" href="#_4-2-版本敏感标记" aria-label="Permalink to &quot;4.2 版本敏感标记&quot;">​</a></h3><p>文章中的“当前”“内部”“通常”“默认”都应紧邻版本说明。升级后重新运行实验、检查 changelog、比对相关测试和源码 diff；不能用旧截图证明新版本行为。</p><h2 id="_5-证据强度实验" tabindex="-1">5. 证据强度实验 <a class="header-anchor" href="#_5-证据强度实验" aria-label="Permalink to &quot;5. 证据强度实验&quot;">​</a></h2><p>保存为 <code>record-environment.mjs</code>，执行 <code>node record-environment.mjs</code>，把输出贴入结论卡：</p><div class="language-js vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">console.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">log</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">({</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  node: process.version,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  v8: process.versions.v8,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  platform: process.platform,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  arch: process.arch</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">})</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Promise</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">resolve</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">().</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">then</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(() </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> console.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">log</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;promise reaction observed&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">))</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">console.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">log</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;synchronous observation&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br></div></div><p>它会先打印环境和同步行，再打印 reaction。该脚本为实验证据补全版本，不会自动获得规范地位；规范链接、源码 commit 与实验输出必须分别保存。</p><h2 id="_6-常见证据错误" tabindex="-1">6. 常见证据错误 <a class="header-anchor" href="#_6-常见证据错误" aria-label="Permalink to &quot;6. 常见证据错误&quot;">​</a></h2><h3 id="_6-1-引用不支持主张" tabindex="-1">6.1 引用不支持主张 <a class="header-anchor" href="#_6-1-引用不支持主张" aria-label="Permalink to &quot;6.1 引用不支持主张&quot;">​</a></h3><p>博客的性能图不能证明标准语义，API 文档也不能证明优化器实现。每个链接都要写出它支持哪一句和不支持哪一句；无法定位的“官方说过”应视为未证实。</p><h3 id="_6-2-用实现掩盖兼容性" tabindex="-1">6.2 用实现掩盖兼容性 <a class="header-anchor" href="#_6-2-用实现掩盖兼容性" aria-label="Permalink to &quot;6.2 用实现掩盖兼容性&quot;">​</a></h3><p>内部函数在一个版本存在，不代表公开稳定或其他引擎具备。对可移植代码，优先依赖规范/公开 API；对诊断文章，允许使用实现细节，但必须标为版本敏感。</p><h2 id="_7-总结" tabindex="-1">7. 总结 <a class="header-anchor" href="#_7-总结" aria-label="Permalink to &quot;7. 总结&quot;">​</a></h2><p>证据不是数量，而是主张、范围与来源层级的匹配。规范证明语义，设计文档解释意图，固定源码说明实现，实验记录观测。把每条结论写成可反驳、可定位、可复现的卡片，才能随版本演进维护原理知识。</p><h2 id="_8-参考资料" tabindex="-1">8. 参考资料 <a class="header-anchor" href="#_8-参考资料" aria-label="Permalink to &quot;8. 参考资料&quot;">​</a></h2><ul><li><a href="https://tc39.es/ecma262/" target="_blank" rel="noreferrer">ECMAScript specification</a></li><li><a href="https://spec.whatwg.org/" target="_blank" rel="noreferrer">WHATWG standards</a></li><li><a href="https://docs.github.com/en/repositories/working-with-files/using-files/getting-permanent-links-to-files" target="_blank" rel="noreferrer">GitHub permanent links</a></li></ul>`,43)])])}const b=e(r,[["render",n]]);export{k as __pageData,b as default};
